import {useEffect,useState,useId,useRef,useCallback} from 'react'
import HypothesisObservations from './HypothesisObservations.jsx'
import HypothesisRevisionComparison from './HypothesisRevisionComparison.jsx'
import HypothesisReviewAcknowledgement from './HypothesisReviewAcknowledgement.jsx'
import HypothesisGenerationLedger from './HypothesisGenerationLedger.jsx'
import HypothesisAssessmentComposer from './HypothesisAssessmentComposer.jsx'
import HypothesisReassessmentRequest,{ReassessmentRequestDetail} from './HypothesisReassessmentRequest.jsx'
import HypothesisAssessmentPanel from './HypothesisAssessmentPanel.jsx'
import {hypothesisHistoryView} from '../lib/hypothesisAssessmentClient.js'
const labels={method_changed:'Evaluated method changed; reassessment required',human_reconsideration:'Human reconsideration requested',retained_assessment_change:'Retained assessment or method changed',retained_source_change:'Retained source changed',workspace_changed:'Investigation definition changed',permission_changed:'Permission requires fresh review'}
export default function HypothesisAssessmentHistory({client,investigationId,userScopeKey,workspaceVersionId,canReconcile=false,onAccessFailure}) {
 const [refresh,setRefresh]=useState(0),[selected,setSelected]=useState(null),[state,setState]=useState(null),[recovery,setRecovery]=useState(null)
 const selectId=useId(),operationEpoch=useRef(0)
 const scope=JSON.stringify([userScopeKey,investigationId,workspaceVersionId,refresh])
 const scopeRef=useRef(scope);scopeRef.current=scope
 const clientRef=useRef(client);clientRef.current=client
 const accessFailure=useRef(onAccessFailure);accessFailure.current=onAccessFailure
 const invalidateAccess=useCallback(code=>{
  if(scopeRef.current!==scope||clientRef.current!==client)return
  setState({client,scope,status:'unavailable'});accessFailure.current?.(code)
 },[client,scope])
 useEffect(()=>{
  operationEpoch.current++
  let current=true
  setState({client,scope,status:'loading'})
  if(!userScopeKey||!investigationId||typeof client?.history!=='function'||typeof client?.backlog!=='function'){
   setState({client,scope,status:'unavailable'});return()=>{current=false;operationEpoch.current++}
  }
  Promise.resolve().then(()=>Promise.all([client.history(investigationId),client.backlog(investigationId)])).then(([history,backlog])=>{
   if(!current)return
   const error=history?.error??backlog?.error
   if(error) {
    setState({client,scope,status:'unavailable'})
    if(['authentication_required','access_denied'].includes(error.code))accessFailure.current?.(error.code)
    return
   }
   const view=hypothesisHistoryView(history.data,backlog.data,investigationId)
   setState(view?{client,scope,status:'ready',view}:{client,scope,status:'unavailable'})
  }).catch(()=>{if(current)setState({client,scope,status:'unavailable'})})
  return()=>{current=false;operationEpoch.current++}
 },[client,investigationId,userScopeKey,workspaceVersionId,scope])
 const reload=()=>{setRecovery(null);setSelected(null);setRefresh(n=>n+1)}
 async function reconcile() {
  if(!canReconcile||typeof client?.reconcile!=='function')return
  const currentScope=scope,epoch=operationEpoch.current
  setState({client,scope,status:'reconciling'})
  try {
   const result=await client.reconcile(investigationId)
   if(scopeRef.current!==currentScope||operationEpoch.current!==epoch)return
   if(result?.error) {
    setState({client,scope:currentScope,status:'unavailable'})
    if(['authentication_required','access_denied'].includes(result.error.code))accessFailure.current?.(result.error.code)
    return
   }
   setRefresh(n=>n+1)
  }catch{if(scopeRef.current===currentScope&&operationEpoch.current===epoch)setState({client,scope:currentScope,status:'unavailable'})}
 }
 if(!userScopeKey)return null
 const current=state?.scope===scope&&state.client===client?state:null
 if(!current||['loading','reconciling'].includes(current.status))return<section className="piw-card" aria-label="Hypothesis assessment history"><p role="status">{current?.status==='reconciling'?'Checking retained changes…':'Loading assessment history…'}</p></section>
 if(current.status!=='ready')return<section className="piw-card"><h2>Hypothesis assessment history</h2><p role="status">Assessment history is unavailable.</p><button type="button" onClick={reload}>Retry assessment history</button></section>
 const {entries,causes}=current.view,entry=entries.find(e=>e.revision_id===selected)??entries.at(-1)
 const related=entry?causes.filter(c=>c.revision_id===entry.revision_id&&c.state==='pending_explicit_reconciliation'):[]
 const resolved=entry?causes.filter(c=>c.revision_id===entry.revision_id&&c.state==='reassessment_recorded'):[]
 const pendingCount=causes.filter(c=>c.state==='pending_explicit_reconciliation').length
 const permissionChanged=related.some(c=>c.kind==='permission_changed')
 return<section className="piw-stack piw-hypothesis-history" aria-label="Hypothesis assessment history">
  <header className="piw-card"><h2>Hypothesis assessment history</h2>
   <p>These are saved revisions. Changes awaiting reassessment do not replace their conclusions.</p>
   {pendingCount?<p>{pendingCount} retained change causes remain pending across these revisions.</p>:null}
   <button type="button" onClick={reload}>Refresh assessment history</button>
   {canReconcile&&typeof client?.reconcile==='function'?<button type="button" onClick={reconcile}>Check for missed changes</button>:null}
   <p>Retained revisions are available here. A verified “as known then” time view is not available yet.</p>
  </header>
  <HypothesisObservations key={'observations:'+scope} client={client} investigationId={investigationId} userScopeKey={userScopeKey}
   onAccessFailure={code=>{setState({client,scope,status:'unavailable'});accessFailure.current?.(code)}}/>
  {canReconcile&&typeof client?.authoringContext==='function'?<HypothesisAssessmentComposer key={scope+(recovery?.scope===scope&&recovery.client===client?recovery.prior:'')} client={client}
   investigationId={investigationId} workspaceVersionId={workspaceVersionId} userScopeKey={userScopeKey} onSaved={reload}
   recoveryPrior={recovery?.scope===scope&&recovery.client===client?recovery.prior:null} onRecoveryClose={()=>setRecovery(null)}
   onAccessFailure={code=>{setState({client,scope,status:'unavailable'});accessFailure.current?.(code)}}/>:null}
  <HypothesisGenerationLedger onRecover={canReconcile&&typeof client?.recoverGeneration==='function'?prior=>setRecovery({scope,client,prior}):undefined} key={'generations:'+scope} client={client} investigationId={investigationId} userScopeKey={userScopeKey}
   onAccessFailure={code=>{setState({client,scope,status:'unavailable'});accessFailure.current?.(code)}}/>
  {entry?<div className="piw-card piw-hypothesis-revision-select"><label htmlFor={selectId}>Saved assessment revision</label>
   <select id={selectId} value={entry.revision_id} onChange={e=>setSelected(e.target.value)}>
    {entries.map(e=><option key={e.revision_id} value={e.revision_id}>Revision {e.revision}{e.status==='withheld'?' — unavailable':''}</option>)}
   </select>
   {related.length?<div role="status"><p>{related.length} recorded change{related.length===1?'':'s'} await explicit reassessment.</p>
    <ul>{related.map(c=><li key={c.cause_id}>{labels[c.kind]}{c.change_position?' · retained change '+c.change_position:''}{c.kind==='human_reconsideration'&&c.detail?.request_id&&typeof client?.requestDetail==='function'?<ReassessmentRequestDetail key={scope+c.cause_id} client={client} investigationId={investigationId} cause={c} scopeKey={scope} onAccessFailure={invalidateAccess}/>:null}</li>)}</ul>
   </div>:null}
   {resolved.length?<div><p>{resolved.length} recorded change{resolved.length===1?'':'s'} {resolved.length===1?'has':'have'} a saved reassessment.</p>
    <ul>{resolved.map(c=><li key={c.cause_id}>{labels[c.kind]} · <button type="button"
      onClick={()=>setSelected(c.resolution_revision_id)}>Open reassessment revision {entries.find(e=>e.revision_id===c.resolution_revision_id)?.revision}</button>{c.kind==='human_reconsideration'&&c.detail?.request_id&&typeof client?.requestDetail==='function'?<ReassessmentRequestDetail key={scope+c.cause_id} client={client} investigationId={investigationId} cause={c} scopeKey={scope} onAccessFailure={invalidateAccess}/>:null}</li>)}</ul>
    <p>A saved reassessment does not approve publication or restore this older assessment’s permissions.</p>
   </div>:null}
  </div>:<p>No completed hypothesis assessments are saved.</p>}
  {entry?<HypothesisRevisionComparison key={'comparison:'+scope+entry.revision_id} view={current.view} revisionId={entry.revision_id}/>:null}
  {canReconcile&&entry&&entry.revision_id===entries.at(-1)?.revision_id&&typeof client?.requestReassessment==='function'?
   <HypothesisReassessmentRequest key={scope+entry.revision_id} client={client} investigationId={investigationId}
    revisionId={entry.revision_id} scopeKey={scope} onRecorded={reload} onAccessFailure={invalidateAccess}/>:null}
  {entry&&entry.status==='available'&&!permissionChanged?<HypothesisReviewAcknowledgement key={'review:'+scope+entry.revision_id} client={client}
   investigationId={investigationId} revisionId={entry.revision_id} revision={entry.revision} userScopeKey={userScopeKey} canReview={canReconcile}
   onAccessFailure={code=>{setState({client,scope,status:'unavailable'});accessFailure.current?.(code)}}/>:null}
  {entry?(entry.status==='withheld'||permissionChanged?<p role="status">This saved assessment is withheld until its evidence permissions and review requirements are satisfied.</p>:
   <HypothesisAssessmentPanel key={entry.revision_id} assessment={entry.assessment}
    dependencyChanged={entry.reassessment_pending||related.length>0}/>):null}
 </section>
}

import {useEffect,useId,useRef,useState} from 'react'
const triggers={contradiction:'Possible contradiction',shared_origin:'Possible shared source origin',methodology:'Method or reasoning needs reconsideration'}
const text=x=>typeof x==='string'&&x.trim().length>0
export default function HypothesisReassessmentRequest({client,investigationId,revisionId,scopeKey,onRecorded,onAccessFailure}) {
 const id=useId(),[trigger,setTrigger]=useState('contradiction'),[reason,setReason]=useState(''),[attempt,setAttempt]=useState(null),[status,setStatus]=useState('idle')
 const failure=useRef(onAccessFailure);failure.current=onAccessFailure
 const alive=useRef(true);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[])
 const attemptRef=useRef(null),inFlight=useRef(false)
 const active=useRef({});active.current={client,scopeKey}
 async function submit(event) {
  event.preventDefault()
  if(inFlight.current||typeof client?.requestReassessment!=='function')return
  if(!attemptRef.current&&typeof globalThis.crypto?.randomUUID!=='function'){setStatus('uncertain');return}
  const input=attemptRef.current??{investigation_id:investigationId,revision_id:revisionId,request_id:globalThis.crypto.randomUUID(),trigger,reason}
  const context=active.current;attemptRef.current=input;inFlight.current=true;setAttempt(input);setStatus('sending')
  try {
   const result=await client.requestReassessment(input)
   if(!alive.current||active.current.client!==context.client||active.current.scopeKey!==context.scopeKey)return
   if(['authentication_required','access_denied'].includes(result?.error?.code)){
    setStatus('uncertain');failure.current?.(result.error.code);return
   }
   const r=result?.data
   if(result?.error||r?.contract_version!=='mip_hypothesis_request_receipt_v1'||r.investigation_id!==investigationId||
     r.request_id!==input.request_id||r.revision_id!==revisionId||r.trigger!==input.trigger||!text(r.cause_id)||
     r.completed_reassessment!==false||r.publication_allowed!==false){setStatus('uncertain');return}
   setStatus('recorded');onRecorded?.()
  }catch{if(alive.current&&active.current.client===context.client&&active.current.scopeKey===context.scopeKey)setStatus('uncertain')}
  finally{inFlight.current=false}
 }
 return <section className="piw-card" aria-label="Request reassessment"><h3>Request reassessment</h3>
  <p>Record a concern for explicit reconsideration. This does not approve a method, change the saved conclusion or authorize publication.</p>
  <form onSubmit={submit}>
   <label htmlFor={id+'-trigger'}>Reason for reconsideration</label>
   <select id={id+'-trigger'} value={trigger} disabled={!!attempt} onChange={e=>setTrigger(e.target.value)}>
    {Object.entries(triggers).map(([value,label])=><option key={value} value={value}>{label}</option>)}
   </select>
   <label htmlFor={id+'-reason'}>What needs reconsideration, and why?</label>
   <textarea id={id+'-reason'} value={reason} maxLength={2000} required disabled={!!attempt}
    onChange={e=>setReason(e.target.value)} />
   <p>Describe the concern using authorized evidence references. The request remains private and does not itself establish the concern as true.</p>
   <button type="submit" disabled={!reason.trim()||status==='sending'||status==='recorded'}>
    {status==='sending'?'Recording request…':attempt?'Retry the same request':'Record reassessment request'}</button>
  </form>
  {status==='uncertain'?<p role="status">Recording is unconfirmed. Retry the same request to recover its receipt. After reopening, check retained changes before creating another request.</p>:null}
  {status==='recorded'?<p role="status">Request recorded. Reassessment remains pending.</p>:null}
 </section>
}
export function ReassessmentRequestDetail({client,investigationId,cause,scopeKey,onAccessFailure}) {
 const [state,setState]=useState(null),active=useRef({});active.current={client,scopeKey}
 const failure=useRef(onAccessFailure);failure.current=onAccessFailure
 const alive=useRef(true);useEffect(()=>{alive.current=true;return()=>{alive.current=false}},[])
 async function inspect() {
  const context=active.current;setState({status:'loading',...context})
  try {
   const result=await client.requestDetail(investigationId,cause.detail.request_id)
   if(!alive.current||active.current.client!==context.client||active.current.scopeKey!==context.scopeKey)return
   if(['authentication_required','access_denied'].includes(result?.error?.code)){
    setState({status:'withheld',...context});failure.current?.(result.error.code);return
   }
   const r=result?.data
   const valid=!result?.error&&r?.contract_version==='mip_hypothesis_request_detail_v1'&&
    r.investigation_id===investigationId&&r.request_id===cause.detail.request_id&&r.cause_id===cause.cause_id&&
    r.revision_id===cause.revision_id&&r.trigger===cause.detail.trigger&&r.publication_allowed===false&&r.is_approval===false
   if(valid&&r.status==='withheld'&&r.withheld_reason==='current_evidence_permission_required'){
    setState({status:'withheld',...context});failure.current?.('access_denied');return
   }
   setState({status:valid&&r.status==='available'&&text(r.reason)?'available':'withheld',reason:valid&&r.status==='available'?r.reason:null,...context})
  }catch{if(alive.current&&active.current.client===context.client&&active.current.scopeKey===context.scopeKey)setState({status:'withheld',...context})}
 }
 const current=state?.client===client&&state.scopeKey===scopeKey?state:null
 return <div><button type="button" onClick={inspect} disabled={current?.status==='loading'}>Inspect reassessment request</button>
  {current?.status==='available'?<p>{current.reason}</p>:current?.status==='withheld'?<p role="status">Request details are unavailable under current access or evidence permissions.</p>:null}
 </div>
}

import test from 'node:test'
import assert from 'node:assert/strict'
import {mkdirSync} from 'node:fs'
import {createRequire} from 'node:module'
import {fileURLToPath,pathToFileURL} from 'node:url'
import {createElement} from 'react'
import TestRenderer,{act} from 'react-test-renderer'
import {hypothesisFixture} from './hypothesisAssessmentFixture.mjs'
import {createHypothesisAssessmentClient,hypothesisHistoryView} from '../src/lib/hypothesisAssessmentClient.js'
const root=fileURLToPath(new URL('../',import.meta.url)),output=root+'tests/.compiled/HypothesisHistory.mjs'
mkdirSync(root+'tests/.compiled',{recursive:true})
const require=createRequire(import.meta.url),esbuild=createRequire(require.resolve('vite/package.json'))('esbuild')
await esbuild.build({absWorkingDir:root,entryPoints:['src/components/HypothesisAssessmentHistory.jsx'],outfile:output,bundle:true,format:'esm',platform:'node',jsx:'automatic',external:['react','react/jsx-runtime']})
const {default:Panel}=await import(pathToFileURL(output))
function fixture(iid='synthetic-question') {
 const first=hypothesisFixture();first.question_id=iid;first.comparison.rationale='Original synthetic assessment.'
 const next=structuredClone(first);Object.assign(next,{id:'synthetic-assessment-2',revision:2,predecessor_id:first.id,
  revision_trigger:'new_evidence',revision_effect:'less_certain'})
 next.comparison.rationale='Later synthetic assessment.'
 const history={contract_version:'mip_hypothesis_history_v1',investigation_id:iid,publication_allowed:false,
  temporal_scope:'retained_versions_only',historical_commit_visibility_qualified:false,
  entries:[first,next].map(r=>({revision_id:r.id,revision:r.revision,completed_at:r.completed_at,status:'available',assessment:r,current_context:true,reassessment_pending:false}))}
 const backlog={contract_version:'mip_hypothesis_reassessment_backlog_v1',investigation_id:iid,
  publication_allowed:false,completed_reassessment:false,coverage:'retained_causes_only',causes:[]}
 const client={history:async()=>({data:history}),backlog:async()=>({data:backlog}),reconcile:async()=>({data:backlog})}
 return{history,backlog,client}
}
const content=tree=>JSON.stringify(tree.toJSON())
const props=client=>({client,investigationId:'synthetic-question',workspaceVersionId:'synthetic-workspace',userScopeKey:'synthetic-user',canReconcile:true})
test('history client carries only explicit request fields and sanitizes errors',async()=>{
 const calls=[],client=createHypothesisAssessmentClient(async(action,input)=>{calls.push({action,input});return{data:{}}})
 await client.history('iid');await client.backlog('iid');await client.reconcile('iid')
 assert.deepEqual(calls.map(c=>c.action),['history','backlog','reconcile'])
 assert.ok(calls.every(c=>Object.keys(c.input).join()==='investigation_id'))
 const denied=createHypothesisAssessmentClient(async()=>({error:{code:'secret-detail',message:'synthetic sensitive detail'}}))
 assert.deepEqual(await denied.history('iid'),{data:null,error:{code:'request_failed'}})
 assert.equal((await createHypothesisAssessmentClient().history('iid')).error.code,'not_configured')
})
test('history mapping rejects cross-scope, public, unsupported temporal and withheld-text responses',()=>{
 for(const change of [h=>h.investigation_id='other',h=>h.publication_allowed=true,h=>h.historical_commit_visibility_qualified=true,
  h=>h.entries[0].status='withheld',h=>h.entries[1].revision=1]){
  const f=fixture();change(f.history)
  assert.equal(hypothesisHistoryView(f.history,f.backlog,'synthetic-question'),null)
 }
 const f=fixture();f.backlog.causes=[{cause_id:'c',revision_id:'not-in-history',kind:'retained_source_change',state:'pending_explicit_reconciliation'}]
 assert.equal(hypothesisHistoryView(f.history,f.backlog,'synthetic-question'),null)
})
test('history panel selects immutable revisions without claiming a verified time reconstruction',async()=>{
 const f=fixture();let tree
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(f.client)))})
 assert.match(content(tree),/Later synthetic assessment/)
 assert.doesNotMatch(content(tree),/Original synthetic assessment/)
 act(()=>tree.root.findByType('select').props.onChange({target:{value:'synthetic-assessment-1'}}))
 assert.match(content(tree),/Original synthetic assessment/)
 assert.match(content(tree),/time view is not available yet/)
 act(()=>tree.unmount())
})
test('pending changes stay separate; permission changes suppress saved text',async()=>{
 for(const kind of ['retained_source_change','retained_assessment_change','permission_changed']){
  const f=fixture();f.backlog.causes=[{cause_id:'c',revision_id:'synthetic-assessment-2',kind,change_position:'9007199254740993',state:'pending_explicit_reconciliation'}]
  let tree;await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(f.client)))})
  assert.match(content(tree),/await explicit reassessment/)
  if(kind==='permission_changed')assert.doesNotMatch(content(tree),/Later synthetic assessment/)
  else{assert.match(content(tree),/Later synthetic assessment/);assert.match(content(tree),/Reassessment is pending/)}
  act(()=>tree.unmount())
 }
})
test('account changes and logout discard old responses and old private text',async()=>{
 const f=fixture();let resolve,tree
 const delayed={...f.client,history:()=>new Promise(r=>{resolve=r})}
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(delayed)))})
 await act(async()=>{tree.update(createElement(Panel,{...props(f.client),userScopeKey:'other-user',investigationId:'other-question'}))})
 await act(async()=>resolve({data:f.history}))
 assert.doesNotMatch(content(tree),/Later synthetic assessment|Original synthetic assessment/)
 await act(async()=>tree.update(createElement(Panel,{...props(f.client),userScopeKey:null})))
 assert.equal(tree.toJSON(),null);act(()=>tree.unmount())
})
test('refresh clears content immediately and revoked access cannot leave the old result displayed',async()=>{
 const f=fixture();let denied=false,failures=[],tree
 const client={...f.client,history:async()=>denied?{error:{code:'access_denied'}}:{data:f.history}}
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,{...props(client),onAccessFailure:code=>failures.push(code)}))})
 assert.match(content(tree),/Later synthetic assessment/);denied=true
 await act(async()=>tree.root.findAllByType('button').find(b=>b.children.join('')==='Refresh assessment history').props.onClick())
 assert.doesNotMatch(content(tree),/Later synthetic assessment/)
 assert.deepEqual(failures,['access_denied']);act(()=>tree.unmount())
})
test('missed-change reconciliation is explicit and cannot mark assessment completed',async()=>{
 const f=fixture();let reconciles=0,tree
 const client={...f.client,reconcile:async()=>{reconciles++;return{data:f.backlog}}}
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(client)))})
 assert.equal(reconciles,0)
 await act(async()=>tree.root.findAllByType('button').find(b=>b.children.join('')==='Check for missed changes').props.onClick())
 assert.equal(reconciles,1);assert.match(content(tree),/Later synthetic assessment/)
 act(()=>tree.unmount())
})

function completedFixture() {
 const f=fixture(),cause='synthetic-completed-cause'
 f.history.entries[1].assessment.reassessment_causes=[{cause_id:cause,reason:'Synthetic saved consideration of this change.'}]
 Object.assign(f.backlog,{contract_version:'mip_hypothesis_reassessment_backlog_v2',is_completion_receipt:false,
  causes:[{cause_id:cause,revision_id:'synthetic-assessment-1',kind:'retained_source_change',state:'reassessment_recorded',
   resolution_revision_id:'synthetic-assessment-2'}]})
 return f
}
test('resolved causes link to the saved reassessment and do not remain pending',async()=>{
 const f=completedFixture();let tree
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(f.client)))})
 act(()=>tree.root.findByType('select').props.onChange({target:{value:'synthetic-assessment-1'}}))
 assert.equal(tree.root.findAllByType('p').some(p=>p.children.join('')==='1 recorded change has a saved reassessment.'),true)
 assert.doesNotMatch(content(tree),/await explicit reassessment|causes remain pending/)
 act(()=>tree.root.findAllByType('button').find(b=>b.children.join('')==='Open reassessment revision 2').props.onClick())
 assert.match(content(tree),/Later synthetic assessment/)
 const details=tree.root.findAllByType('details').find(d=>d.props.className==='piw-linked-record')
 act(()=>{const node={open:true};details.props.onToggle({target:node,currentTarget:node})})
 assert.match(content(tree),/Synthetic saved consideration/)
 assert.match(content(tree),/separate from review approval and publication eligibility/)
 act(()=>tree.unmount())
})
test('history and resolution snapshots must agree before completed assessment text is revealed',()=>{
 for(const change of [f=>f.backlog.causes[0].state='pending_explicit_reconciliation',
  f=>f.backlog.causes[0].resolution_revision_id='synthetic-assessment-1',
  f=>f.history.entries[1].assessment.reassessment_causes[0].cause_id='different',
  f=>f.backlog.contract_version='mip_hypothesis_reassessment_backlog_v1']){
  const f=completedFixture();change(f)
  assert.equal(hypothesisHistoryView(f.history,f.backlog,'synthetic-question'),null)
 }
})
test('resolving a permission cause does not restore withheld prior assessment text',async()=>{
 const f=completedFixture()
 f.backlog.causes[0].kind='permission_changed'
 Object.assign(f.history.entries[0],{status:'withheld',reason:'permission_binding_changed_fresh_review_required'})
 delete f.history.entries[0].assessment
 let tree;await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(f.client)))})
 act(()=>tree.root.findByType('select').props.onChange({target:{value:'synthetic-assessment-1'}}))
 assert.match(content(tree),/saved assessment is withheld/)
 assert.doesNotMatch(content(tree),/Original synthetic assessment/)
 assert.match(content(tree),/does not approve publication or restore/)
 act(()=>tree.unmount())
})

test('history comparison clears on refresh denial and logout',async()=>{
 const f=fixture();let denied=false,tree
 const client={...f.client,history:async()=>denied?{error:{code:'access_denied'}}:{data:f.history}}
 await act(async()=>{tree=TestRenderer.create(createElement(Panel,props(client)))})
 const comparison=tree.root.findAllByType('details').find(d=>d.findAllByType('summary').some(s=>s.children.join('').startsWith('Inspect changes')))
 act(()=>{const node={open:true};comparison.props.onToggle({target:node,currentTarget:node})})
 assert.match(content(tree),/Original synthetic assessment/)
 denied=true
